// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: from address, an array length (as uint8 to keep gas/size reasonable), and values for each element
    function testFuzz_property(address from, uint8 len, uint256 seed) public {
        // keep length reasonable and > 0 because require(_tos.length > 0) in contract
        uint8 boundedLen = len == 0 ? 1 : len; // ensure at least 1
        vm.assume(boundedLen <= 10); // keep array small for gas

        // prepare arrays
        address[] memory tos = new address[](boundedLen);
        uint[] memory vals = new uint[](boundedLen);

        // deterministically fill arrays from seed so fuzzer explores values
        for (uint8 i = 0; i < boundedLen; i++) {
            // craft distinct but deterministic addresses using seed
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, i, from)))));
            vals[i] = uint256(keccak256(abi.encodePacked(seed, i, from, uint256(i))));
        }

        // We must call c.transfer and observe its returned boolean. The property: reference returns true for any inputs that don't revert.
        // Invoke and capture whether the call completed (did not revert) and what it returned.
        bool ok;
        bool ret;
        try c.transfer(from, address(0), tos, vals) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // The general rule: if the call does not revert (ok==true) then the reference contract returns true.
        // We assert that: ok implies ret == true. This will hold on reference C for all inputs, but fail on the mutant
        // (which returns false when it doesn't revert for some inputs), allowing the fuzzer to find such inputs.
        assertTrue(!ok || ret);
    }
}
